import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.BUwdTBzS.js";const b=JSON.parse('{"title":"浏览器兼容性规范","description":"浏览器兼容性强制规范 - 禁用超出项目基线的 JS API 和 CSS 属性","frontmatter":{"title":"浏览器兼容性规范","description":"浏览器兼容性强制规范 - 禁用超出项目基线的 JS API 和 CSS 属性"},"headers":[],"relativePath":"rules/浏览器兼容性规范.md","filePath":"rules/浏览器兼容性规范.md","lastUpdated":null}'),a={name:"rules/浏览器兼容性规范.md"};function c(l,t,i,h,s,n){return e(),o("div",null,[...t[0]||(t[0]=[r('<blockquote><p>📄 本页由源文件 <code>rules/浏览器兼容性规范.mdc</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="浏览器兼容性规范" tabindex="-1">浏览器兼容性规范 <a class="header-anchor" href="#浏览器兼容性规范" aria-label="Permalink to &quot;浏览器兼容性规范&quot;">​</a></h1><p>本规则为浏览器兼容性检查的<strong>单一真相源</strong>，由 <code>browser-compat</code> skill 和 <code>code-review</code> L1 审查按需加载。</p><hr><h2 id="一、目标浏览器基线-项目可覆盖" tabindex="-1">一、目标浏览器基线（项目可覆盖） <a class="header-anchor" href="#一、目标浏览器基线-项目可覆盖" aria-label="Permalink to &quot;一、目标浏览器基线（项目可覆盖）&quot;">​</a></h2><p>项目通过 <code>package.json &gt; browserslist</code> 或 <code>.browser-compat.json</code> 声明基线；未声明时使用「保守型」默认。</p><table tabindex="0"><thead><tr><th>基线级别</th><th>适用场景</th><th>Chrome</th><th>Safari</th><th>Firefox</th><th>Edge</th><th>ES 级别</th></tr></thead><tbody><tr><td><strong>保守型</strong>（默认）</td><td>企业客户端 Web、C 端门户</td><td>70+</td><td>12+</td><td>68+</td><td>79+</td><td>ES2019</td></tr><tr><td><strong>标准型</strong></td><td>管理后台 / 内部工具</td><td>90+</td><td>14+</td><td>90+</td><td>90+</td><td>ES2021</td></tr><tr><td><strong>激进型</strong></td><td>Chrome-only 内嵌、Electron</td><td>100+</td><td>—</td><td>—</td><td>—</td><td>ES2022+</td></tr></tbody></table><p>本规则所列「禁用」默认针对 <strong>保守型</strong> 基线；标准型/激进型下部分条目可放宽，按项目实际 browserslist 判定。</p><hr><h2 id="二、js-禁用-api-清单" tabindex="-1">二、JS 禁用 API 清单 <a class="header-anchor" href="#二、js-禁用-api-清单" aria-label="Permalink to &quot;二、JS 禁用 API 清单&quot;">​</a></h2><h3 id="🔴-critical-保守型必须禁用-检测到即-block" tabindex="-1">🔴 CRITICAL（保守型必须禁用，检测到即 Block） <a class="header-anchor" href="#🔴-critical-保守型必须禁用-检测到即-block" aria-label="Permalink to &quot;🔴 CRITICAL（保守型必须禁用，检测到即 Block）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>禁用原因</th><th>替代方案</th></tr></thead><tbody><tr><td><code>Array.prototype.at()</code></td><td>Safari 15.4+ / Chrome 92+</td><td><code>arr[arr.length - 1]</code> 或 <code>arr.slice(-1)[0]</code></td></tr><tr><td><code>structuredClone()</code></td><td>Safari 15.4+ / Chrome 98+</td><td><code>JSON.parse(JSON.stringify(x))</code> 或 <code>lodash.cloneDeep</code></td></tr><tr><td><code>Object.hasOwn()</code></td><td>Safari 15.4+ / Chrome 93+</td><td><code>Object.prototype.hasOwnProperty.call(obj, key)</code></td></tr><tr><td><code>Array.prototype.toSorted/toReversed/toSpliced</code></td><td>Safari 16+ / Chrome 110+</td><td><code>[...arr].sort()</code> / <code>[...arr].reverse()</code></td></tr><tr><td><code>Object.groupBy</code> / <code>Map.groupBy</code></td><td>Safari 17.4+ / Chrome 117+</td><td><code>arr.reduce((acc, x) =&gt; { ... })</code></td></tr><tr><td><code>Promise.withResolvers</code></td><td>Safari 17.4+ / Chrome 119+</td><td><code>let resolve, reject; new Promise((r, j) =&gt; { resolve = r; reject = j; })</code></td></tr><tr><td><code>crypto.randomUUID()</code></td><td>Safari 15.4+ / Chrome 92+</td><td><code>uuid</code> npm 包</td></tr></tbody></table><h3 id="🟡-warning-保守型下需确认项目已引入-polyfill" tabindex="-1">🟡 WARNING（保守型下需确认项目已引入 polyfill） <a class="header-anchor" href="#🟡-warning-保守型下需确认项目已引入-polyfill" aria-label="Permalink to &quot;🟡 WARNING（保守型下需确认项目已引入 polyfill）&quot;">​</a></h3><blockquote><p>注：以下 🟡 条目<strong>仅作为 AI 生成代码时的上下文参考</strong>，当前 <code>scripts/compat-check.js</code> 暂不做自动检测（假设项目已统一 polyfill 或特性检测）。如需扫描，建议在 <code>code-review</code> L1/L2 手动确认 polyfill 是否就位。</p></blockquote><table tabindex="0"><thead><tr><th>API</th><th>说明</th></tr></thead><tbody><tr><td><code>ResizeObserver</code></td><td>项目应已 polyfill，否则 Safari 13.1 以下不可用</td></tr><tr><td><code>IntersectionObserver</code></td><td>项目应已 polyfill</td></tr><tr><td><code>requestIdleCallback</code></td><td>Safari 不支持，使用前要特性检测或 setTimeout 降级</td></tr></tbody></table><hr><h2 id="三、css-禁用属性清单" tabindex="-1">三、CSS 禁用属性清单 <a class="header-anchor" href="#三、css-禁用属性清单" aria-label="Permalink to &quot;三、CSS 禁用属性清单&quot;">​</a></h2><h3 id="🔴-critical-保守型必须禁用" tabindex="-1">🔴 CRITICAL（保守型必须禁用） <a class="header-anchor" href="#🔴-critical-保守型必须禁用" aria-label="Permalink to &quot;🔴 CRITICAL（保守型必须禁用）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性/特性</th><th>禁用原因</th><th>替代方案</th></tr></thead><tbody><tr><td><code>:has()</code> 选择器</td><td>Safari 15.4+ / Chrome 105+</td><td>JS 逻辑 + className 切换</td></tr><tr><td><code>container-type</code> / 容器查询</td><td>Safari 16+ / Chrome 105+</td><td><code>ResizeObserver</code> + JS</td></tr><tr><td><code>color-mix()</code></td><td>Safari 16.2+ / Chrome 111+</td><td>CSS 变量 + 预计算</td></tr><tr><td><code>subgrid</code></td><td>Safari 16+ / Chrome 117+</td><td>嵌套 grid 或重新设计布局</td></tr><tr><td>Flexbox <code>gap</code></td><td>Safari 14.1+（12 不支持）</td><td><code>margin</code> + 负 margin 抵消</td></tr><tr><td><code>aspect-ratio</code></td><td>Safari 15.4+ / Chrome 88+</td><td><code>padding-bottom</code> 百分比技巧</td></tr><tr><td><code>inset</code> 简写</td><td>Safari 14.1+</td><td>展开为 <code>top/right/bottom/left</code></td></tr><tr><td><code>text-wrap: balance/pretty</code></td><td>Safari 17.5+ / Chrome 114+</td><td>不使用，让浏览器默认换行</td></tr><tr><td><code>@layer</code> 级联层</td><td>Safari 15.4+ / Chrome 99+</td><td>使用选择器优先级控制层级</td></tr><tr><td><code>accent-color</code></td><td>Safari 15.4+ / Chrome 93+</td><td>自定义 checkbox/radio 样式</td></tr></tbody></table><h3 id="🟡-warning-需加前缀或降级方案" tabindex="-1">🟡 WARNING（需加前缀或降级方案） <a class="header-anchor" href="#🟡-warning-需加前缀或降级方案" aria-label="Permalink to &quot;🟡 WARNING（需加前缀或降级方案）&quot;">​</a></h3><blockquote><p>注：以下 🟡 条目中，<code>scripts/compat-check.js</code> 当前<strong>仅实现 <code>backdrop-filter</code> 缺失 <code>-webkit-</code> 前缀的检测</strong>；<code>overscroll-behavior</code> / <code>clamp()</code> / <code>scroll-behavior</code> 仅作为 AI 生成代码时的上下文参考，不参与自动扫描。</p></blockquote><table tabindex="0"><thead><tr><th>属性</th><th>说明</th></tr></thead><tbody><tr><td><code>backdrop-filter</code></td><td>需 <code>-webkit-backdrop-filter</code> 前缀 + 不支持时的兜底背景色</td></tr><tr><td><code>overscroll-behavior</code></td><td>需 <code>touch-action</code> 兜底</td></tr><tr><td><code>clamp()</code> / 复杂 <code>calc()</code></td><td>Safari 12 对 <code>calc()</code> 中单位除法支持不完整</td></tr><tr><td><code>scroll-behavior: smooth</code></td><td>Safari 15.4+ 才支持，动画类可用 JS 平滑滚动替代</td></tr></tbody></table><hr><h2 id="四、检查时机" tabindex="-1">四、检查时机 <a class="header-anchor" href="#四、检查时机" aria-label="Permalink to &quot;四、检查时机&quot;">​</a></h2><ol><li><p><strong>AI 生成代码时</strong>（本规则的首要作用）</p><ul><li>对照上述清单，禁止直接输出 🔴 项的代码</li><li>🟡 项输出时必须注明降级方案或确认 polyfill 已就位</li></ul></li><li><p><strong><code>code-review</code> L1 审查第 5 条</strong></p><ul><li>调用 <code>use_skill(&#39;browser-compat&#39;)</code> 对本轮 diff 执行 <code>compat-check.js</code></li><li>🔴 违规 → 强制修复后才能进入下一步</li><li>🟡 违规 → 弹出用户决策（修复 / 加降级 / 跳过）</li></ul></li><li><p><strong>独立使用</strong></p><ul><li>用户说&quot;检查兼容性&quot;/&quot;这段代码能用吗&quot; → 直接触发 <code>browser-compat</code> skill</li></ul></li><li><p><strong>项目级 pre-commit hook</strong>（可选）</p><ul><li>项目安装 <code>scripts/git-hook-check.js</code> 后，commit 前自动扫描 staged 文件</li></ul></li></ol><hr><h2 id="五、例外处理" tabindex="-1">五、例外处理 <a class="header-anchor" href="#五、例外处理" aria-label="Permalink to &quot;五、例外处理&quot;">​</a></h2><ul><li>项目 <code>.browser-compat.json</code> 的 <code>ignore</code> 字段可声明允许使用的 API/属性（需在文件中写明业务理由）</li><li>代码行级豁免：<code>// @compat-ignore: 原因</code> 或 <code>/* @compat-ignore: 原因 */</code></li><li>全局 polyfill 已引入的项目在 <code>.browser-compat.json &gt; polyfills</code> 中声明，检测脚本自动排除对应规则</li></ul><hr><h2 id="六、规则版本" tabindex="-1">六、规则版本 <a class="header-anchor" href="#六、规则版本" aria-label="Permalink to &quot;六、规则版本&quot;">​</a></h2><ul><li>v1.0（2026-05-07）：初版，覆盖保守型基线下的核心 JS/CSS 禁用清单</li><li>v1.1（2026-05-08）：🟡 WARNING 段前新增&quot;脚本覆盖度&quot;说明，明确自动扫描边界</li></ul>',31)])])}const u=d(a,[["render",c]]);export{b as __pageData,u as default};
